# frozen_string_literal: true

module Security
  module SecretDetection
    module PartnerTokens
      # Auto-generated by ClientGenerator from a reviewed VendorDefinition.
      # Vendor docs: https://docs.highnote.com/docs/developers/api/using-the-api
      # Regenerate rather than hand-editing; keep the VendorDefinition as the source of truth.
      class HighnoteLiveClient < BaseClient
        API_ENDPOINT = "https://api.us.highnote.com/graphql?query=%7B__typename%7D"

        private

        def partner_name
          "highnote"
        end

        def verify_partner_token(token_value)
          response = make_request(
            API_ENDPOINT,
            method: :get,
            headers: {
              'Authorization' => "Basic #{Base64.strict_encode64("#{token_value}:")}",
              "apollo-require-preflight" => "true",
              'Accept' => 'application/json'
            }
          )
          analyze_response(response)
        end

        def analyze_response(response)
          case response.code.to_i
          when 200
            token_response(:active)
          when 401
            token_response(:inactive)
          when 429
            raise RateLimitError, "highnote rate limited: #{response.code}"
          when 500, 502, 503, 504
            raise NetworkError, "highnote service error: #{response.code}"
          else
            # unknown-never-inactive: unmapped codes are never treated as dead tokens.
            token_response(:unknown)
          end
        end
      end
    end
  end
